class Enemy:
    def __init__(self, x, y, patrol_range=120):
        self.x = x
        self.y = y
        self.w = 30
        self.h = 30
        self.start_x = x
        self.vx = -1.5
        self.vy = 0
        self.alive = True
        self.frame = 0
        self.patrol_range = patrol_range
        self.squish_timer = 0

    def update(self, solids):
        if not self.alive:
            self.squish_timer -= 1
            return

        self.vy += GRAVITY
        if self.vy > 10:
            self.vy = 10

        self.x += self.vx
        self.y += self.vy

        # 巡逻范围
        if abs(self.x - self.start_x) > self.patrol_range:
            self.vx = -self.vx

        # 地面碰撞
        rect = pygame.Rect(self.x, self.y, self.w, self.h)
        for s in solids:
            if rect.colliderect(s):
                if self.vy > 0:
                    self.y = s.top - self.h
                    self.vy = 0
                elif self.vx > 0:
                    self.x = s.left - self.w
                    self.vx = -self.vx
                elif self.vx < 0:
                    self.x = s.right
                    self.vx = -self.vx
                rect = pygame.Rect(self.x, self.y, self.w, self.h)

        # 掉落
        if self.y > SCREEN_H + 100:
            self.alive = False

        self.frame += 1

    def squish(self):
        self.alive = False
        self.squish_timer = 20
        self.h = 10

    def draw(self, surface, cam_x):
        if self.squish_timer <= 0 and not self.alive:
            return
        if self.alive:
            draw_goomba(surface, self.x - cam_x, self.y, self.w, self.h, self.frame)
        else:
            pygame.draw.ellipse(surface, (150, 50, 50), (self.x - cam_x, self.y, self.w, self.h))

    def get_rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)

