def parse_level(level_data):
    """将文本关卡数据解析为游戏对象"""
    blocks = []
    coins = []
    enemies = []
    flag = None
    player_start = (TILE * 2, TILE * 12)

    for row_idx, row in enumerate(level_data):
        for col_idx, char in enumerate(row):
            x = col_idx * TILE
            y = row_idx * TILE

            if char == 'G':
                blocks.append(Block(x, y, 'ground'))
            elif char == 'B':
                blocks.append(Block(x, y, 'brick'))
            elif char == '?':
                blocks.append(Block(x, y, 'question'))
            elif char == 'P':
                blocks.append(Block(x, y, 'pipe'))
            elif char == 'C':
                coins.append(Coin(x + 10, y + 8))
            elif char == 'E':
                enemies.append(Enemy(x, y))
            elif char == 'F':
                flag = Flag(x, y)

    return blocks, coins, enemies, flag, player_start

def get_solids(blocks):
    """获取所有固体碰撞矩形"""
    return [b.get_rect() for b in blocks]
